{
  "path": [
    {
      "step": 1,
      "course_id": "EDX1848",
      "rationale": "This foundational course provides strategies for approaching math effectively, correcting misconceptions, and building confidence in math abilities."
    },
    {
      "step": 2,
      "course_id": "EDX1017",
      "rationale": "Building on the foundational course, this course provides a grounding in arithmetic and algebra, an overview of functions, and an introduction to financial mathematics."
    },
    {
      "step": 3,
      "course_id": "EDX2137",
      "rationale": "This course further develops algebra and geometry, explores modeling of common relations and functions, and introduces precalculus concepts."
    },
    {
      "step": 4,
      "course_id": "EDX1322",
      "rationale": "This course focuses on algebraic methods, graphs, and applied mathematics, building on the precalculus concepts introduced earlier."
    },
    {
      "step": 5,
      "course_id": "EDX1500",
      "rationale": "This advanced course covers calculus, kinematics, and optimization problems, providing a comprehensive understanding of mathematical concepts."
    }
  ]
}

{
  "path": [
    {
      "step": 1,
      "course_id": "EDX2160",
      "rationale": "This course provides a foundational understanding of statistics, which is essential for educational assessment and measuring student learning."
    },
    {
      "step": 2,
      "course_id": "EDX1929",
      "rationale": "This course builds on the foundational understanding of statistics by applying it to instructional design and evaluation, which is a critical aspect of educational assessment."
    },
    {
      "step": 3,
      "course_id": "EDX2607",
      "rationale": "This course provides advanced knowledge of statistics and data analysis, which is necessary for measuring student learning and making data-driven decisions in education."
    },
    {
      "step": 4,
      "course_id": "EDX1861",
      "rationale": "This course applies the knowledge of statistics and data analysis to real-world scenarios in education, which is essential for making informed decisions about student learning."
    }
  ]
}

